  1 | package config
  2 | 
  3 | import (
  4 | 	"log"
  5 | 	"os"
  6 | 	"strconv"
  7 | 	"strings"
  8 | 	"time"
  9 | 
 10 | 	"github.com/joho/godotenv"
 11 | )
 12 | 
 13 | const (
 14 | 	// EmailProviderSES delivers OTP mails through AWS SES (default, production).
 15 | 	EmailProviderSES = "ses"
 16 | 	// EmailProviderLog only logs the mail body — meant for local development.
 17 | 	EmailProviderLog = "log"
 18 | )
 19 | 
 20 | // Config holds every runtime setting of the API. Only the values marked
 21 | // required are mandatory at boot; everything else falls back to a sane
 22 | // default so a fresh clone can run with just Turso + JWT_SECRET.
 23 | type Config struct {
 24 | 	// ---- Server ----
 25 | 	ServerPort     string
 26 | 	AllowedOrigins []string
 27 | 
 28 | 	// ---- Turso (libSQL) ----
 29 | 	TursoURL   string
 30 | 	TursoToken string
 31 | 
 32 | 	// ---- Tokens ----
 33 | 	JWTSecret       string
 34 | 	JWTIssuer       string
 35 | 	AccessTokenTTL  time.Duration
 36 | 	RefreshTokenTTL time.Duration
 37 | 
 38 | 	// ---- Admin auth policy ----
 39 | 	TwoFARequired     bool
 40 | 	OTPLength         int
 41 | 	OTPTTL            time.Duration
 42 | 	OTPMaxAttempts    int
 43 | 	OTPMaxPerWindow   int
 44 | 	OTPWindow         time.Duration
 45 | 	OTPResendCooldown time.Duration
 46 | 	MinPasswordLength int
 47 | 	LoginMaxAttempts  int
 48 | 	LoginWindow       time.Duration
 49 | 
 50 | 	// ---- Email / AWS SES ----
 51 | 	EmailProvider       string
 52 | 	AWSRegion           string
 53 | 	AWSAccessKeyID      string
 54 | 	AWSSecretAccessKey  string
 55 | 	AWSSessionToken     string
 56 | 	SESEndpointURL      string
 57 | 	SESFromEmail        string
 58 | 	SESFromName         string
 59 | 	SESReplyTo          string
 60 | 	SESConfigurationSet string
 61 | }
 62 | 
 63 | // Load reads .env (when present) plus the process environment and validates
 64 | // the result. It exits the process on an unusable configuration so that a
 65 | // misconfigured container fails loudly instead of serving broken traffic.
 66 | func Load() *Config {
 67 | 	if err := godotenv.Load(); err != nil {
 68 | 		log.Println("No .env file found, using environment variables")
 69 | 	}
 70 | 
 71 | 	cfg := &Config{
 72 | 		// PORT is set by the Lambda Web Adapter; SERVER_PORT wins locally.
 73 | 		ServerPort:     getEnv("SERVER_PORT", getEnv("PORT", "8080")),
 74 | 		AllowedOrigins: getEnvCSV("AUTH_ALLOWED_ORIGINS", []string{"http://localhost:5173", "http://localhost:3000"}),
 75 | 
 76 | 		TursoURL:   os.Getenv("TURSO_DATABASE_URL"),
 77 | 		TursoToken: os.Getenv("TURSO_AUTH_TOKEN"),
 78 | 
 79 | 		JWTSecret:       os.Getenv("JWT_SECRET"),
 80 | 		JWTIssuer:       getEnv("JWT_ISSUER", "portfolio-api"),
 81 | 		AccessTokenTTL:  getEnvMinutes("JWT_ACCESS_TTL_MINUTES", 15),
 82 | 		RefreshTokenTTL: getEnvDays("JWT_REFRESH_TTL_DAYS", 30),
 83 | 
 84 | 		TwoFARequired:     getEnvBool("AUTH_2FA_REQUIRED", true),
 85 | 		OTPLength:         getEnvInt("AUTH_OTP_LENGTH", 6),
 86 | 		OTPTTL:            getEnvMinutes("AUTH_OTP_TTL_MINUTES", 10),
 87 | 		OTPMaxAttempts:    getEnvInt("AUTH_OTP_MAX_ATTEMPTS", 5),
 88 | 		OTPMaxPerWindow:   getEnvInt("AUTH_OTP_MAX_PER_WINDOW", 5),
 89 | 		OTPWindow:         getEnvMinutes("AUTH_OTP_WINDOW_MINUTES", 60),
 90 | 		OTPResendCooldown: getEnvSeconds("AUTH_OTP_RESEND_COOLDOWN_SECONDS", 30),
 91 | 		MinPasswordLength: getEnvInt("AUTH_MIN_PASSWORD_LENGTH", 12),
 92 | 		LoginMaxAttempts:  getEnvInt("AUTH_LOGIN_MAX_ATTEMPTS", 10),
 93 | 		LoginWindow:       getEnvMinutes("AUTH_LOGIN_WINDOW_MINUTES", 15),
 94 | 
 95 | 		EmailProvider:       strings.ToLower(getEnv("EMAIL_PROVIDER", EmailProviderSES)),
 96 | 		AWSRegion:           getEnv("AWS_REGION", "ap-south-1"),
 97 | 		AWSAccessKeyID:      os.Getenv("AWS_ACCESS_KEY_ID"),
 98 | 		AWSSecretAccessKey:  os.Getenv("AWS_SECRET_ACCESS_KEY"),
 99 | 		AWSSessionToken:     os.Getenv("AWS_SESSION_TOKEN"),
100 | 		SESEndpointURL:      os.Getenv("SES_ENDPOINT_URL"),
101 | 		SESFromEmail:        os.Getenv("SES_FROM_EMAIL"),
102 | 		SESFromName:         getEnv("SES_FROM_NAME", "Portfolio Admin"),
103 | 		SESReplyTo:          os.Getenv("SES_REPLY_TO"),
104 | 		SESConfigurationSet: os.Getenv("SES_CONFIGURATION_SET"),
105 | 	}
106 | 
107 | 	cfg.validate()
108 | 	return cfg
109 | }
110 | 
111 | // validate fails the boot when a required setting is missing or nonsensical.
112 | func (c *Config) validate() {
113 | 	if c.TursoURL == "" || c.TursoToken == "" {
114 | 		log.Fatal("TURSO_DATABASE_URL and TURSO_AUTH_TOKEN must be set")
115 | 	}
116 | 	if len(c.JWTSecret) < 32 {
117 | 		log.Fatal("JWT_SECRET must be set and at least 32 characters long")
118 | 	}
119 | 	if c.EmailProvider != EmailProviderSES && c.EmailProvider != EmailProviderLog {
120 | 		log.Fatalf("EMAIL_PROVIDER must be %q or %q (got %q)", EmailProviderSES, EmailProviderLog, c.EmailProvider)
121 | 	}
122 | 	if c.EmailProvider == EmailProviderSES {
123 | 		if c.SESFromEmail == "" {
124 | 			log.Fatal("SES_FROM_EMAIL must be set when EMAIL_PROVIDER=ses")
125 | 		}
126 | 		if c.AWSRegion == "" {
127 | 			log.Fatal("AWS_REGION must be set when EMAIL_PROVIDER=ses")
128 | 		}
129 | 		if (c.AWSAccessKeyID == "") != (c.AWSSecretAccessKey == "") {
130 | 			log.Fatal("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set together (omit both to use the Lambda IAM role)")
131 | 		}
132 | 	}
133 | 	if c.OTPLength < 4 || c.OTPLength > 10 {
134 | 		log.Fatal("AUTH_OTP_LENGTH must be between 4 and 10")
135 | 	}
136 | 	if c.MinPasswordLength < 8 {
137 | 		log.Fatal("AUTH_MIN_PASSWORD_LENGTH must be at least 8")
138 | 	}
139 | }
140 | 
141 | // UsesSES reports whether real mails are sent through AWS SES.
142 | func (c *Config) UsesSES() bool { return c.EmailProvider == EmailProviderSES }
143 | 
144 | // MailFrom renders the RFC 5322 From header, e.g. `Portfolio Admin <no-reply@x.com>`.
145 | func (c *Config) MailFrom() string {
146 | 	if c.SESFromName == "" {
147 | 		return c.SESFromEmail
148 | 	}
149 | 	return c.SESFromName + " <" + c.SESFromEmail + ">"
150 | }
151 | 
152 | func getEnv(key, fallback string) string {
153 | 	if v, ok := os.LookupEnv(key); ok && v != "" {
154 | 		return v
155 | 	}
156 | 	return fallback
157 | }
158 | 
159 | func getEnvInt(key string, fallback int) int {
160 | 	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
161 | 		n, err := strconv.Atoi(strings.TrimSpace(v))
162 | 		if err != nil {
163 | 			log.Fatalf("%s must be an integer (got %q)", key, v)
164 | 		}
165 | 		return n
166 | 	}
167 | 	return fallback
168 | }
169 | 
170 | func getEnvBool(key string, fallback bool) bool {
171 | 	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
172 | 		b, err := strconv.ParseBool(strings.TrimSpace(v))
173 | 		if err != nil {
174 | 			log.Fatalf("%s must be a boolean (got %q)", key, v)
175 | 		}
176 | 		return b
177 | 	}
178 | 	return fallback
179 | }
180 | 
181 | func getEnvMinutes(key string, fallback int) time.Duration {
182 | 	return time.Duration(getEnvInt(key, fallback)) * time.Minute
183 | }
184 | 
185 | func getEnvSeconds(key string, fallback int) time.Duration {
186 | 	return time.Duration(getEnvInt(key, fallback)) * time.Second
187 | }
188 | 
189 | func getEnvDays(key string, fallback int) time.Duration {
190 | 	return time.Duration(getEnvInt(key, fallback)) * 24 * time.Hour
191 | }
192 | 
193 | func getEnvCSV(key string, fallback []string) []string {
194 | 	v, ok := os.LookupEnv(key)
195 | 	if !ok || strings.TrimSpace(v) == "" {
196 | 		return fallback
197 | 	}
198 | 	out := make([]string, 0, len(fallback))
199 | 	for _, p := range strings.Split(v, ",") {
200 | 		if trimmed := strings.TrimSpace(p); trimmed != "" {
201 | 			out = append(out, trimmed)
202 | 		}
203 | 	}
204 | 	if len(out) == 0 {
205 | 		return fallback
206 | 	}
207 | 	return out
208 | }

 1 | package email
 2 | 
 3 | import (
 4 | 	"context"
 5 | 	"fmt"
 6 | 
 7 | 	"github.com/aws/aws-sdk-go-v2/aws"
 8 | 	awsconfig "github.com/aws/aws-sdk-go-v2/config"
 9 | 	"github.com/aws/aws-sdk-go-v2/credentials"
10 | 	"github.com/aws/aws-sdk-go-v2/service/sesv2"
11 | 	sestypes "github.com/aws/aws-sdk-go-v2/service/sesv2/types"
12 | 	"github.com/coderkamlesh/portfolio_api/internal/config"
13 | )
14 | 
15 | // SESSender delivers mail through Amazon SES v2 (SendEmail).
16 | //
17 | // Credentials are resolved in this order, matching how the AWS SDK works:
18 | //  1. AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY / AWS_SESSION_TOKEN (all optional)
19 | //  2. the Lambda execution role (recommended in production — leave the keys empty)
20 | //  3. the standard AWS chain (shared config file, ECS/EC2 metadata)
21 | type SESSender struct {
22 | 	client           *sesv2.Client
23 | 	from             string
24 | 	replyTo          []string
25 | 	configurationSet string
26 | }
27 | 
28 | // NewSESSender builds a SES-backed sender. It loads the AWS default config,
29 | // which fails fast if the region or credentials are unusable.
30 | func NewSESSender(ctx context.Context, cfg *config.Config) (*SESSender, error) {
31 | 	loadOpts := []func(*awsconfig.LoadOptions) error{
32 | 		awsconfig.WithRegion(cfg.AWSRegion),
33 | 	}
34 | 	if cfg.AWSAccessKeyID != "" && cfg.AWSSecretAccessKey != "" {
35 | 		loadOpts = append(loadOpts, awsconfig.WithCredentialsProvider(
36 | 			credentials.NewStaticCredentialsProvider(
37 | 				cfg.AWSAccessKeyID, cfg.AWSSecretAccessKey, cfg.AWSSessionToken,
38 | 			),
39 | 		))
40 | 	}
41 | 
42 | 	awsCfg, err := awsconfig.LoadDefaultConfig(ctx, loadOpts...)
43 | 	if err != nil {
44 | 		return nil, fmt.Errorf("email: load AWS config: %w", err)
45 | 	}
46 | 
47 | 	var clientOpts []func(*sesv2.Options)
48 | 	if cfg.SESEndpointURL != "" {
49 | 		// LocalStack / VPC endpoint override.
50 | 		clientOpts = append(clientOpts, func(o *sesv2.Options) {
51 | 			o.BaseEndpoint = aws.String(cfg.SESEndpointURL)
52 | 		})
53 | 	}
54 | 
55 | 	sender := &SESSender{
56 | 		client:           sesv2.NewFromConfig(awsCfg, clientOpts...),
57 | 		from:             cfg.MailFrom(),
58 | 		configurationSet: cfg.SESConfigurationSet,
59 | 	}
60 | 	if cfg.SESReplyTo != "" {
61 | 		sender.replyTo = []string{cfg.SESReplyTo}
62 | 	}
63 | 	return sender, nil
64 | }
65 | 
66 | // Send delivers msg through SES.
67 | func (s *SESSender) Send(ctx context.Context, msg Message) error {
68 | 	body := &sestypes.Body{
69 | 		Text: &sestypes.Content{Data: aws.String(msg.TextBody), Charset: aws.String("UTF-8")},
70 | 	}
71 | 	if msg.HTMLBody != "" {
72 | 		body.Html = &sestypes.Content{Data: aws.String(msg.HTMLBody), Charset: aws.String("UTF-8")}
73 | 	}
74 | 
75 | 	input := &sesv2.SendEmailInput{
76 | 		FromEmailAddress: aws.String(s.from),
77 | 		Destination:      &sestypes.Destination{ToAddresses: []string{msg.To}},
78 | 		ReplyToAddresses: s.replyTo,
79 | 		Content: &sestypes.EmailContent{
80 | 			Simple: &sestypes.Message{
81 | 				Subject: &sestypes.Content{Data: aws.String(msg.Subject), Charset: aws.String("UTF-8")},
82 | 				Body:    body,
83 | 			},
84 | 		},
85 | 	}
86 | 	if s.configurationSet != "" {
87 | 		input.ConfigurationSetName = aws.String(s.configurationSet)
88 | 	}
89 | 
90 | 	if _, err := s.client.SendEmail(ctx, input); err != nil {
91 | 		return fmt.Errorf("email: ses send to %s: %w", msg.To, err)
92 | 	}
93 | 	return nil
94 | }

