232 | // findAdmin resolves -username or -email to an account.
233 | func findAdmin(ctx context.Context, admins *repository.AdminRepository, identifier string) (*models.AdminUser, error) {
234 | 	identifier = strings.TrimSpace(identifier)
235 | 	if identifier == "" {
236 | 		return nil, errors.New("-username (or -email) is required")
237 | 	}
238 | 
239 | 	account, err := admins.FindByIdentifier(ctx, identifier)
240 | 	if err != nil {
