249 | // resolvePassword returns the -password flag value, or reads one line from
250 | // stdin so the password never has to appear in the shell history.
251 | func resolvePassword(flagValue string) (string, error) {
252 | 	if flagValue != "" {
253 | 		return flagValue, nil
254 | 	}
255 | 
256 | 	fmt.Fprint(os.Stderr, "Password (echoed by your terminal; pipe it in to keep it out of history): ")
257 | 	reader := bufio.NewReader(os.Stdin)
258 | 	line, err := reader.ReadString('\n')
259 | 	if err != nil && line == "" {
260 | 		return "", fmt.Errorf("could not read password from stdin: %w", err)
261 | 	}
262 | 	password := strings.TrimRight(line, "\r\n")
263 | 	if password == "" {
264 | 		return "", errors.New("password must not be empty")
265 | 	}
266 | 	return password, nil
267 | }

