  1 | // Package handler exposes the auth service over HTTP (chi). Handlers only
  2 | // decode/validate the request, call the service and encode the response —
  3 | // all rules live in the service layer.
  4 | package handler
  5 | 
  6 | import (
  7 | 	"encoding/json"
  8 | 	"errors"
  9 | 	"fmt"
 10 | 	"io"
 11 | 	"log"
 12 | 	"net"
 13 | 	"net/http"
 14 | 	"strconv"
 15 | 	"strings"
 16 | 
 17 | 	"github.com/coderkamlesh/portfolio_api/internal/apierr"
 18 | 	"github.com/coderkamlesh/portfolio_api/internal/service"
 19 | )
 20 | 
 21 | // maxBodyBytes caps request bodies — auth payloads are tiny.
 22 | const maxBodyBytes = 64 * 1024
 23 | 
 24 | // errorEnvelope is the shape of every failed response:
 25 | //
 26 | //	{"error": {"code": "invalid_credentials", "message": "…"}}
 27 | type errorEnvelope struct {
 28 | 	Error errorBody `json:"error"`
 29 | }
 30 | 
 31 | type errorBody struct {
 32 | 	Code    string `json:"code"`
 33 | 	Message string `json:"message"`
 34 | }
 35 | 
 36 | // writeJSON serialises payload with the given status code.
 37 | func writeJSON(w http.ResponseWriter, status int, payload any) {
 38 | 	w.Header().Set("Content-Type", "application/json; charset=utf-8")
 39 | 	w.Header().Set("Cache-Control", "no-store")
 40 | 	w.WriteHeader(status)
 41 | 	if payload == nil {
 42 | 		return
 43 | 	}
 44 | 	if err := json.NewEncoder(w).Encode(payload); err != nil {
 45 | 		log.Printf("⚠️  handler: encode response failed: %v", err)
 46 | 	}
 47 | }
 48 | 
 49 | // writeNoContent answers 204.
 50 | func writeNoContent(w http.ResponseWriter) {
 51 | 	w.Header().Set("Cache-Control", "no-store")
 52 | 	w.WriteHeader(http.StatusNoContent)
 53 | }
 54 | 
 55 | // writeErr maps any error to the JSON error envelope. Internal errors are
 56 | // logged with their cause but never exposed.
 57 | func writeErr(w http.ResponseWriter, r *http.Request, err error) {
 58 | 	apiErr := apierr.From(err)
 59 | 	if apiErr.Status >= http.StatusInternalServerError {
 60 | 		log.Printf("❌ handler: %s %s -> %d %s: %v", r.Method, r.URL.Path, apiErr.Status, apiErr.Code, apiErr.Err)
 61 | 	}
 62 | 	if apiErr.RetryAfter > 0 {
 63 | 		w.Header().Set("Retry-After", strconv.Itoa(apiErr.RetryAfter))
 64 | 	}
 65 | 	writeJSON(w, apiErr.Status, errorEnvelope{Error: errorBody{Code: apiErr.Code, Message: apiErr.Message}})
 66 | }
 67 | 
 68 | // decodeJSON reads a single JSON object with strict field checking.
 69 | func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) error {
 70 | 	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
 71 | 
 72 | 	decoder := json.NewDecoder(r.Body)
 73 | 	decoder.DisallowUnknownFields()
 74 | 
 75 | 	if err := decoder.Decode(dst); err != nil {
 76 | 		switch {
 77 | 		case errors.Is(err, io.EOF):
 78 | 			return apierr.BadRequest("empty_body", "The request body is required.")
 79 | 		case strings.Contains(err.Error(), "http: request body too large"):
 80 | 			return apierr.BadRequest("body_too_large", "The request body is too large.")
 81 | 		default:
 82 | 			return apierr.Wrap(err, http.StatusBadRequest, "invalid_json",
 83 | 				fmt.Sprintf("The request body is not valid JSON: %s", err.Error()))
 84 | 		}
 85 | 	}
 86 | 	if decoder.More() {
 87 | 		return apierr.BadRequest("invalid_json", "The request body must contain a single JSON object.")
 88 | 	}
 89 | 	return nil
 90 | }
 91 | 
 92 | // requestMeta extracts the caller fingerprint stored with sessions/audit rows.
 93 | // net/http + chi's RealIP already resolve X-Forwarded-For into RemoteAddr.
 94 | func requestMeta(r *http.Request) service.RequestMeta {
 95 | 	return service.RequestMeta{
 96 | 		IPAddress: clientIP(r),
 97 | 		UserAgent: truncate(r.UserAgent(), 255),
 98 | 	}
 99 | }
100 | 
101 | func clientIP(r *http.Request) string {
102 | 	host, _, err := net.SplitHostPort(r.RemoteAddr)
103 | 	if err != nil {
104 | 		return r.RemoteAddr
105 | 	}
106 | 	return host
107 | }
108 | 
109 | func truncate(v string, max int) string {
110 | 	if len(v) > max {
111 | 		return v[:max]
112 | 	}
113 | 	return v
114 | }
115 | 
116 | // requiredString trims a field and rejects it when empty. `field` is used in
117 | // the message so the admin panel can show which input is missing.
118 | func requiredString(value, field string) (string, error) {
119 | 	value = strings.TrimSpace(value)
120 | 	if value == "" {
121 | 		return "", requiredFieldError(field)
122 | 	}
123 | 	return value, nil
124 | }
125 | 
126 | // requiredFieldError reports a missing field in the request body.
127 | func requiredFieldError(field string) error {
128 | 	return apierr.BadRequest("validation_failed", field+" is required.")
129 | }
130 | 
131 | // unauthorizedContextError is a defensive guard: it fires only if a protected
132 | // route is ever registered without RequireAuth.
133 | func unauthorizedContextError() error {
134 | 	return apierr.Unauthorized("unauthorized", "Authentication required.")
135 | }

