 16 | // Deps wires the service to its collaborators. Every field is an interface so
 17 | // the auth flows can be unit-tested with in-memory doubles.
 18 | type Deps struct {
 19 | 	Admins  AdminStore
 20 | 	TwoFA   TwoFAStore
