 45 | // NewAuthService builds the service.
 46 | func NewAuthService(deps Deps) *AuthService {
 47 | 	now := deps.Now
 48 | 	if now == nil {
 49 | 		now = func() time.Time { return time.Now().UTC() }
 50 | 	}
 51 | 	return &AuthService{
 52 | 		admins:       deps.Admins,
 53 | 		twoFA:        deps.TwoFA,
 54 | 		otps:         deps.OTPs,
 55 | 		refresh:      deps.Refresh,
 56 | 		audit:        deps.Audit,
 57 | 		mailer:       deps.Mailer,
 58 | 		tokens:       deps.Tokens,
 59 | 		cfg:          deps.Cfg,
 60 | 		now:          now,
 61 | 		loginLimiter: security.NewLimiter(deps.Cfg.LoginMaxAttempts, deps.Cfg.LoginWindow),
 62 | 	}
