 65 | // Login validates the password. When email-OTP 2FA applies it mails a code and
 66 | // returns a challenge; otherwise it signs the admin in directly (only possible
 67 | // when AUTH_2FA_REQUIRED=false and the method was disabled).
 68 | func (s *AuthService) Login(ctx context.Context, in LoginInput, meta RequestMeta) (*LoginResult, error) {
 69 | 	identifier := strings.TrimSpace(in.Identifier)
 70 | 	if identifier == "" || in.Password == "" {
 71 | 		return nil, errInvalidCredentials()
 72 | 	}
 73 | 
 74 | 	limitKey := security.ClientKey(identifier, meta.IPAddress)
 75 | 	if !s.loginLimiter.Allow(limitKey) {
 76 | 		s.auditEvent(ctx, "", models.AuditRateLimited, "login", map[string]any{"identifier": identifier})
 77 | 		return nil, errRateLimited(int(s.loginLimiter.RetryAfter(limitKey).Seconds()) + 1)
 78 | 	}
 79 | 
 80 | 	admin, err := s.admins.FindByIdentifier(ctx, identifier)
 81 | 	if err != nil {
 82 | 		if errors.Is(err, models.ErrNotFound) {
 83 | 			// Burn the same CPU as a real verification so the response time
 84 | 			// does not disclose whether the account exists.
 85 | 			_, _ = security.VerifyPassword(security.DummyPasswordHash, in.Password)
 86 | 			s.loginLimiter.RegisterFailure(limitKey)
 87 | 			s.auditEvent(ctx, "", models.AuditLoginFailed, "unknown_identifier", map[string]any{"identifier": identifier})
 88 | 			return nil, errInvalidCredentials()
 89 | 		}
 90 | 		return nil, err
 91 | 	}
 92 | 
 93 | 	if !admin.IsActive {
 94 | 		s.loginLimiter.RegisterFailure(limitKey)
 95 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "inactive", nil)
 96 | 		return nil, errAccountDisabled()
 97 | 	}
 98 | 
 99 | 	ok, err := security.VerifyPassword(admin.PasswordHash, in.Password)
100 | 	if err != nil {
101 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
102 | 	}
103 | 	if !ok {
104 | 		s.loginLimiter.RegisterFailure(limitKey)
105 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "bad_password", nil)
106 | 		return nil, errInvalidCredentials()
107 | 	}
108 | 	s.loginLimiter.Reset(limitKey)
109 | 
110 | 	// Opportunistically upgrade hashes produced with weaker parameters.
111 | 	if security.NeedsRehash(admin.PasswordHash) {
112 | 		if hash, err := security.HashPassword(in.Password); err == nil {
113 | 			if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
114 | 				log.Printf("⚠️  auth: password rehash failed for admin %s: %v", admin.ID, err)
115 | 			}
116 | 		}
117 | 	}
118 | 
119 | 	_, required, err := s.emailTwoFAConfig(ctx, admin)
120 | 	if err != nil {
121 | 		return nil, err
122 | 	}
123 | 
124 | 	if !required {
125 | 		tokens, err := s.issueSession(ctx, admin, meta)
126 | 		if err != nil {
127 | 			return nil, err
128 | 		}
129 | 		if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
130 | 			log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
131 | 		}
132 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginSucceeded, "password_only", nil)
133 | 		return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
134 | 	}
135 | 
136 | 	challenge, err := s.issueOTP(ctx, admin, models.OTPPurposeLogin2FA, meta)
137 | 	if err != nil {
138 | 		return nil, err
139 | 	}
140 | 	s.auditEvent(ctx, admin.ID, models.AuditLoginChallenged, "email_otp", nil)
141 | 	return &LoginResult{TwoFactorRequired: true, Challenge: challenge}, nil
142 | }
143 | 
144 | // VerifyLoginOTP completes the second factor and starts a session.
145 | func (s *AuthService) VerifyLoginOTP(ctx context.Context, in VerifyOTPInput, meta RequestMeta) (*LoginResult, error) {
146 | 	challenge, err := s.loadChallenge(ctx, in.ChallengeID, models.OTPPurposeLogin2FA)
147 | 	if err != nil {
148 | 		return nil, err
149 | 	}
150 | 
151 | 	admin, err := s.checkOTP(ctx, challenge, in.OTP)
152 | 	if err != nil {
153 | 		return nil, err
154 | 	}
155 | 
156 | 	if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
157 | 		log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
158 | 	}
159 | 
160 | 	tokens, err := s.issueSession(ctx, admin, meta)
161 | 	if err != nil {
162 | 		return nil, err
163 | 	}
164 | 	s.auditEvent(ctx, admin.ID, models.AuditLoginSucceeded, "email_otp", nil)
165 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
166 | }
167 | 
168 | // ResendLoginOTP invalidates the previous code and mails a fresh one, subject
169 | // to the resend cooldown so the endpoint cannot be used to spam the admin.
170 | func (s *AuthService) ResendLoginOTP(ctx context.Context, in ResendOTPInput, meta RequestMeta) (*ChallengeView, error) {
171 | 	challenge, err := s.otps.FindByID(ctx, in.ChallengeID)
172 | 	if err != nil {
173 | 		if errors.Is(err, models.ErrNotFound) {
174 | 			return nil, errInvalidChallenge()
175 | 		}
176 | 		return nil, err
177 | 	}
178 | 	if challenge.Purpose != models.OTPPurposeLogin2FA || challenge.IsConsumed() {
179 | 		return nil, errChallengeUsed()
180 | 	}
181 | 
182 | 	admin, err := s.adminFor(ctx, challenge.AdminID)
183 | 	if err != nil {
184 | 		return nil, err
185 | 	}
186 | 	if !admin.IsActive {
187 | 		return nil, errAccountDisabled()
188 | 	}
189 | 
190 | 	if pending, err := s.otps.FindLatestPending(ctx, admin.ID, models.OTPPurposeLogin2FA, s.now()); err == nil {
191 | 		availableAt := pending.CreatedAt.Add(s.cfg.OTPResendCooldown)
192 | 		if s.now().Before(availableAt) {
193 | 			return nil, errOTPCooldown(int(availableAt.Sub(s.now()).Seconds()) + 1)
194 | 		}
195 | 	} else if !errors.Is(err, models.ErrNotFound) {
196 | 		return nil, err
197 | 	}
198 | 
199 | 	view, err := s.issueOTP(ctx, admin, models.OTPPurposeLogin2FA, meta)
