 12 | )
 13 | 
 14 | // issueOTP invalidates any pending challenge of the same purpose, mails a new
 15 | // code and returns the client-facing view of the challenge.
 16 | //
 17 | // Guard rails: at most AUTH_OTP_MAX_PER_WINDOW codes per AUTH_OTP_WINDOW_MINUTES
 18 | // per admin, argon2id-hashed codes, and a hard expiry of AUTH_OTP_TTL_MINUTES.
 19 | func (s *AuthService) issueOTP(ctx context.Context, admin *models.AdminUser, purpose string, meta RequestMeta) (*ChallengeView, error) {
 20 | 	now := s.now()
 21 | 
 22 | 	sent, err := s.otps.CountCreatedSince(ctx, admin.ID, purpose, now.Add(-s.cfg.OTPWindow))
 23 | 	if err != nil {
 24 | 		return nil, err
 25 | 	}
 26 | 	if sent >= s.cfg.OTPMaxPerWindow {
 27 | 		s.auditEvent(ctx, admin.ID, models.AuditRateLimited, "otp_window", map[string]any{"sent": sent})
 28 | 		return nil, errOTPTooManyRequests()
 29 | 	}
 30 | 
 31 | 	// Only the newest code may be used.
 32 | 	if err := s.otps.InvalidatePending(ctx, admin.ID, purpose, now); err != nil {
 33 | 		return nil, err
 34 | 	}
 35 | 
 36 | 	code, err := security.GenerateOTP(s.cfg.OTPLength)
 37 | 	if err != nil {
 38 | 		return nil, wrapErr(err, 500, "internal_error", "Could not generate a verification code.")
 39 | 	}
 40 | 	otpHash, err := security.HashOTP(code)
 41 | 	if err != nil {
 42 | 		return nil, wrapErr(err, 500, "internal_error", "Could not generate a verification code.")
 43 | 	}
 44 | 
 45 | 	challenge := &models.OTPChallenge{
 46 | 		ID:        ids.New(),
 47 | 		AdminID:   admin.ID,
 48 | 		OTPHash:   otpHash,
 49 | 		Purpose:   purpose,
 50 | 		ExpiresAt: now.Add(s.cfg.OTPTTL),
 51 | 		CreatedAt: now,
 52 | 	}
 53 | 	if err := s.otps.Create(ctx, challenge); err != nil {
 54 | 		return nil, err
 55 | 	}
 56 | 
 57 | 	msg := email.OTPMessage(admin.Email, email.OTPMail{
 58 | 		Code:        code,
 59 | 		Purpose:     purpose,
 60 | 		TTL:         s.cfg.OTPTTL,
 61 | 		RequestedAt: now,
 62 | 		IPAddress:   meta.IPAddress,
 63 | 		UserAgent:   sanitizeUserAgent(meta.UserAgent),
 64 | 	})
 65 | 	if err := s.mailer.Send(ctx, msg); err != nil {
 66 | 		log.Printf("❌ auth: otp mail failed for admin %s: %v", admin.ID, err)
 67 | 		if _, consumeErr := s.otps.Consume(ctx, challenge.ID, s.now()); consumeErr != nil {
 68 | 			log.Printf("⚠️  auth: could not consume unsent challenge %s: %v", challenge.ID, consumeErr)
 69 | 		}
 70 | 		return nil, errEmailDeliveryFailed(err)
 71 | 	}
 72 | 
 73 | 	s.pruneExpired(ctx)
 74 | 	return s.challengeView(challenge, admin.Email), nil
 75 | }
