 77 | // loadChallenge fetches a challenge and validates its purpose and state,
 78 | // consuming nothing.
 79 | func (s *AuthService) loadChallenge(ctx context.Context, challengeID, purpose string) (*models.OTPChallenge, error) {
 80 | 	if challengeID == "" {
 81 | 		return nil, errInvalidChallenge()
 82 | 	}
 83 | 	challenge, err := s.otps.FindByID(ctx, challengeID)
 84 | 	if err != nil {
 85 | 		if errors.Is(err, models.ErrNotFound) {
 86 | 			return nil, errInvalidChallenge()
 87 | 		}
 88 | 		return nil, err
 89 | 	}
 90 | 	if challenge.Purpose != purpose {
 91 | 		return nil, errInvalidChallenge()
 92 | 	}
 93 | 	if challenge.IsConsumed() {
 94 | 		return nil, errChallengeUsed()
 95 | 	}
 96 | 	if challenge.IsExpired(s.now()) {
 97 | 		return nil, errChallengeExpired()
 98 | 	}
 99 | 	if challenge.AttemptCount >= s.cfg.OTPMaxAttempts {
100 | 		return nil, errOTPAttemptsExceeded()
101 | 	}
102 | 	return challenge, nil
103 | }
104 | 
105 | // checkOTP verifies the submitted code, burns one attempt on failure and
106 | // consumes the challenge on success. It returns the owning admin.
107 | func (s *AuthService) checkOTP(ctx context.Context, challenge *models.OTPChallenge, code string) (*models.AdminUser, error) {
108 | 	admin, err := s.adminFor(ctx, challenge.AdminID)
109 | 	if err != nil {
110 | 		return nil, err
111 | 	}
112 | 	if !admin.IsActive {
113 | 		return nil, errAccountDisabled()
114 | 	}
115 | 
116 | 	code = security.NormalizeOTP(code)
117 | 	if code == "" {
118 | 		return nil, errInvalidOTP(s.cfg.OTPMaxAttempts - challenge.AttemptCount)
119 | 	}
120 | 
121 | 	ok, err := security.VerifyOTP(challenge.OTPHash, code)
122 | 	if err != nil {
123 | 		return nil, wrapErr(err, 500, "internal_error", "Stored verification code is unreadable.")
124 | 	}
125 | 	if !ok {
126 | 		attempts, incErr := s.otps.IncrementAttempts(ctx, challenge.ID)
127 | 		if incErr != nil {
128 | 			log.Printf("⚠️  auth: could not record otp attempt for %s: %v", challenge.ID, incErr)
129 | 			attempts = challenge.AttemptCount + 1
130 | 		}
131 | 		s.auditEvent(ctx, admin.ID, models.AuditOTPFailed,
132 | 			"invalid_code", map[string]any{"attempt": attempts, "purpose": challenge.Purpose})
133 | 
134 | 		if remaining := s.cfg.OTPMaxAttempts - attempts; remaining > 0 {
135 | 			return nil, errInvalidOTP(remaining)
136 | 		}
137 | 		if _, consumeErr := s.otps.Consume(ctx, challenge.ID, s.now()); consumeErr != nil {
138 | 			log.Printf("⚠️  auth: could not consume locked challenge %s: %v", challenge.ID, consumeErr)
139 | 		}
140 | 		return nil, errOTPAttemptsExceeded()
141 | 	}
142 | 
143 | 	// One-shot: a conditional UPDATE guarantees a single winner on races.
144 | 	consumed, err := s.otps.Consume(ctx, challenge.ID, s.now())
145 | 	if err != nil {
146 | 		return nil, err
147 | 	}
148 | 	if !consumed {
149 | 		return nil, errChallengeUsed()
150 | 	}
151 | 	return admin, nil
152 | }
153 | 
154 | // challengeView projects a challenge for the API response.
155 | func (s *AuthService) challengeView(c *models.OTPChallenge, emailAddress string) *ChallengeView {
156 | 	return &ChallengeView{
157 | 		ID:           c.ID,
158 | 		Purpose:      c.Purpose,
159 | 		Email:        security.MaskEmail(emailAddress),
160 | 		CodeLength:   s.cfg.OTPLength,
161 | 		ExpiresAt:    c.ExpiresAt,
162 | 		ExpiresIn:    maxInt(int(c.ExpiresAt.Sub(s.now()).Seconds()), 0),
163 | 		AttemptsLeft: maxInt(s.cfg.OTPMaxAttempts-c.AttemptCount, 0),
164 | 		ResendAfter:  int(s.cfg.OTPResendCooldown.Seconds()),
165 | 	}
166 | }
167 | 
168 | func maxInt(a, b int) int {
169 | 	if a > b {
170 | 		return a
171 | 	}
172 | 	return b
173 | }

