  2 | 
  3 | import (
  4 | 	"context"
  5 | 	"errors"
  6 | 	"log"
  7 | 
  8 | 	"github.com/coderkamlesh/portfolio_api/internal/models"
  9 | 	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
 10 | 	"github.com/coderkamlesh/portfolio_api/internal/security"
 11 | )
 12 | 
 13 | // issueSession mints an access token plus a rotating opaque refresh token.
 14 | // Only the SHA-256 hash of the refresh token is persisted.
 15 | func (s *AuthService) issueSession(ctx context.Context, admin *models.AdminUser, meta RequestMeta) (*TokenPair, error) {
 16 | 	accessToken, accessExpiresAt, err := s.tokens.IssueAccessToken(admin)
 17 | 	if err != nil {
 18 | 		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
 19 | 	}
 20 | 
 21 | 	refreshToken, err := security.GenerateRefreshToken()
 22 | 	if err != nil {
 23 | 		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
 24 | 	}
 25 | 
 26 | 	now := s.now()
 27 | 	refreshExpiresAt := now.Add(s.cfg.RefreshTokenTTL)
 28 | 	record := &models.RefreshToken{
 29 | 		ID:        ids.New(),
 30 | 		AdminID:   admin.ID,
 31 | 		TokenHash: security.HashToken(refreshToken),
 32 | 		ExpiresAt: refreshExpiresAt,
 33 | 		UserAgent: sanitizeUserAgent(meta.UserAgent),
 34 | 		IPAddress: meta.IPAddress,
 35 | 		CreatedAt: now,
 36 | 	}
 37 | 	if err := s.refresh.Create(ctx, record); err != nil {
 38 | 		return nil, err
 39 | 	}
 40 | 
 41 | 	return &TokenPair{
 42 | 		TokenType:        "Bearer",
 43 | 		AccessToken:      accessToken,
 44 | 		ExpiresIn:        int(s.tokens.AccessTTL().Seconds()),
 45 | 		ExpiresAt:        accessExpiresAt,
 46 | 		RefreshToken:     refreshToken,
 47 | 		RefreshExpiresIn: int(s.cfg.RefreshTokenTTL.Seconds()),
 48 | 		RefreshExpiresAt: refreshExpiresAt,
 49 | 	}, nil
 50 | }
 51 | 
 52 | // Refresh rotates a refresh token: the presented token is revoked and a fresh
 53 | // pair is issued. Replaying an already-revoked token revokes every session of
 54 | // that admin, which is the standard protection against a stolen token.
 55 | func (s *AuthService) Refresh(ctx context.Context, in RefreshInput, meta RequestMeta) (*LoginResult, error) {
 56 | 	if in.RefreshToken == "" {
 57 | 		return nil, errInvalidRefreshToken()
 58 | 	}
 59 | 
 60 | 	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
 61 | 	if err != nil {
 62 | 		if errors.Is(err, models.ErrNotFound) {
 63 | 			return nil, errInvalidRefreshToken()
 64 | 		}
 65 | 		return nil, err
 66 | 	}
 67 | 
 68 | 	now := s.now()
 69 | 
 70 | 	if record.RevokedAt != nil {
 71 | 		s.revokeAllSessions(ctx, record.AdminID, "refresh_token_reuse")
 72 | 		return nil, errRefreshTokenReused()
 73 | 	}
 74 | 	if !now.Before(record.ExpiresAt) {
 75 | 		if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
 76 | 			log.Printf("⚠️  auth: could not revoke expired token %s: %v", record.ID, err)
 77 | 		}
 78 | 		return nil, errInvalidRefreshToken()
 79 | 	}
 80 | 
 81 | 	admin, err := s.adminFor(ctx, record.AdminID)
 82 | 	if err != nil {
 83 | 		return nil, err
 84 | 	}
 85 | 	if !admin.IsActive {
 86 | 		s.revokeAllSessions(ctx, admin.ID, "account_disabled")
 87 | 		return nil, errAccountDisabled()
 88 | 	}
 89 | 
 90 | 	rotated, err := s.refresh.Revoke(ctx, record.ID, now)
 91 | 	if err != nil {
 92 | 		return nil, err
 93 | 	}
 94 | 	if !rotated {
 95 | 		// Someone else rotated it a moment ago — treat as reuse.
 96 | 		s.revokeAllSessions(ctx, admin.ID, "refresh_token_race")
 97 | 		return nil, errRefreshTokenReused()
 98 | 	}
 99 | 
100 | 	tokens, err := s.issueSession(ctx, admin, meta)
101 | 	if err != nil {
102 | 		return nil, err
103 | 	}
104 | 	s.auditEvent(ctx, admin.ID, models.AuditTokenRefreshed, "", nil)
105 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
106 | }
107 | 
108 | // Logout revokes one session, or every session of the admin.
109 | func (s *AuthService) Logout(ctx context.Context, adminID string, in LogoutInput) error {
110 | 	now := s.now()
111 | 
112 | 	if in.AllDevices || in.RefreshToken == "" {
113 | 		if _, err := s.refresh.RevokeAllForAdmin(ctx, adminID, now); err != nil {
114 | 			return err
115 | 		}
116 | 		s.auditEvent(ctx, adminID, models.AuditLoggedOut, "all_devices", nil)
117 | 		return nil
118 | 	}
119 | 
120 | 	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
121 | 	if err != nil {
122 | 		if errors.Is(err, models.ErrNotFound) {
123 | 			return nil // already gone — logging out is idempotent
124 | 		}
125 | 		return err
126 | 	}
127 | 	if record.AdminID != adminID {
128 | 		return errInvalidRefreshToken()
129 | 	}
130 | 	if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
131 | 		return err
132 | 	}
133 | 	s.auditEvent(ctx, adminID, models.AuditLoggedOut, "single_device", nil)
134 | 	return nil
135 | }
136 | 
137 | // CurrentAdmin powers GET /api/auth/me.
138 | func (s *AuthService) CurrentAdmin(ctx context.Context, adminID string) (*MeView, error) {
139 | 	admin, err := s.admins.FindByID(ctx, adminID)
140 | 	if err != nil {
141 | 		if errors.Is(err, models.ErrNotFound) {
142 | 			return nil, errInvalidRefreshToken()
143 | 		}
144 | 		return nil, err
145 | 	}
146 | 	if !admin.IsActive {
147 | 		return nil, errAccountDisabled()
148 | 	}
149 | 
150 | 	status, err := s.TwoFAStatus(ctx, admin)
151 | 	if err != nil {
152 | 		return nil, err
153 | 	}
154 | 	sessions, err := s.refresh.CountActive(ctx, admin.ID, s.now())
155 | 	if err != nil {
156 | 		log.Printf("⚠️  auth: could not count sessions for %s: %v", admin.ID, err)
157 | 		sessions = 0
158 | 	}
159 | 
160 | 	return &MeView{Admin: adminView(admin), TwoFactor: status, ActiveSession: sessions}, nil
161 | }
162 | 
163 | // revokeAllSessions revokes every refresh token of the admin and records why.
164 | func (s *AuthService) revokeAllSessions(ctx context.Context, adminID, reason string) {
165 | 	if _, err := s.refresh.RevokeAllForAdmin(ctx, adminID, s.now()); err != nil {
166 | 		log.Printf("⚠️  auth: revoke all sessions failed for %s: %v", adminID, err)
167 | 	}
168 | 	s.auditEvent(ctx, adminID, models.AuditTokenReuseDetected, reason, nil)
169 | }

