 10 | // ChangePassword handles POST /api/auth/password/change and returns a fresh
 11 | // token pair for the current device (all other sessions are revoked).
 12 | func (h *AuthHandler) ChangePassword(w http.ResponseWriter, r *http.Request) {
 13 | 	adminID, ok := middleware.AdminIDFromContext(r.Context())
 14 | 	if !ok {
 15 | 		writeErr(w, r, unauthorizedContextError())
 16 | 		return
 17 | 	}
 18 | 
 19 | 	var body changePasswordRequest
 20 | 	if err := decodeJSON(w, r, &body); err != nil {
 21 | 		writeErr(w, r, err)
 22 | 		return
 23 | 	}
 24 | 	if body.CurrentPassword == "" {
 25 | 		writeErr(w, r, requiredFieldError("current_password"))
 26 | 		return
 27 | 	}
 28 | 	if body.NewPassword == "" {
 29 | 		writeErr(w, r, requiredFieldError("new_password"))
 30 | 		return
 31 | 	}
 32 | 
 33 | 	tokens, err := h.svc.ChangePassword(r.Context(), adminID, service.ChangePasswordInput{
 34 | 		CurrentPassword: body.CurrentPassword,
 35 | 		NewPassword:     body.NewPassword,
 36 | 	}, requestMeta(r))
 37 | 	if err != nil {
 38 | 		writeErr(w, r, err)
 39 | 		return
 40 | 	}
 41 | 	writeJSON(w, http.StatusOK, map[string]any{"tokens": tokens})
 42 | }
