 45 | func (h *AuthHandler) ForgotPassword(w http.ResponseWriter, r *http.Request) {
 46 | 	var body forgotPasswordRequest
 47 | 	if err := decodeJSON(w, r, &body); err != nil {
 48 | 		writeErr(w, r, err)
 49 | 		return
 50 | 	}
 51 | 	if _, err := requiredString(body.Email, "email"); err != nil {
 52 | 		writeErr(w, r, err)
 53 | 		return
 54 | 	}
 55 | 
 56 | 	if err := h.svc.ForgotPassword(r.Context(), service.ForgotPasswordInput{Email: body.Email}, requestMeta(r)); err != nil {
 57 | 		writeErr(w, r, err)
 58 | 		return
 59 | 	}
 60 | 	// Always the same answer, whether or not the address exists.
