 66 | // ResetPassword handles POST /api/auth/password/reset.
 67 | func (h *AuthHandler) ResetPassword(w http.ResponseWriter, r *http.Request) {
 68 | 	var body resetPasswordRequest
 69 | 	if err := decodeJSON(w, r, &body); err != nil {
 70 | 		writeErr(w, r, err)
 71 | 		return
 72 | 	}
 73 | 	if _, err := requiredString(body.ChallengeID, "challenge_id"); err != nil {
 74 | 		writeErr(w, r, err)
 75 | 		return
 76 | 	}
 77 | 	if _, err := requiredString(body.OTP, "otp"); err != nil {
 78 | 		writeErr(w, r, err)
 79 | 		return
 80 | 	}
 81 | 	if body.NewPassword == "" {
 82 | 		writeErr(w, r, requiredFieldError("new_password"))
 83 | 		return
 84 | 	}
 85 | 
 86 | 	result, err := h.svc.ResetPassword(r.Context(), service.ResetPasswordInput{
 87 | 		ChallengeID: body.ChallengeID,
 88 | 		OTP:         body.OTP,
 89 | 		NewPassword: body.NewPassword,
 90 | 	}, requestMeta(r))
 91 | 	if err != nil {
 92 | 		writeErr(w, r, err)
 93 | 		return
 94 | 	}
 95 | 	writeJSON(w, http.StatusOK, result)
 96 | }
