 1 | // Package middleware holds the cross-cutting HTTP concerns: bearer-token
 2 | // authentication, CORS for the admin panel, request logging and cache headers.
 3 | package middleware
 4 | 
 5 | import (
 6 | 	"context"
 7 | 	"net/http"
 8 | 	"strings"
 9 | 
10 | 	"github.com/coderkamlesh/portfolio_api/internal/apierr"
11 | 	"github.com/coderkamlesh/portfolio_api/internal/security"
12 | )
13 | 
14 | type contextKey string
15 | 
16 | const claimsContextKey contextKey = "auth.access_claims"
17 | 
18 | // RequireAuth validates the `Authorization: Bearer <jwt>` header and stores the
19 | // access-token claims in the request context.
20 | func RequireAuth(tokens *security.TokenManager) func(http.Handler) http.Handler {
21 | 	return func(next http.Handler) http.Handler {
22 | 		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
23 | 			raw := bearerToken(r)
24 | 			if raw == "" {
25 | 				writeAuthError(w, apierr.Unauthorized("missing_token", "Authorization header with a bearer token is required."))
26 | 				return
27 | 			}
28 | 
29 | 			claims, err := tokens.ParseAccessToken(raw)
30 | 			if err != nil {
31 | 				writeAuthError(w, apierr.Wrap(err, http.StatusUnauthorized, "invalid_token",
32 | 					"Your session is invalid or has expired. Please sign in again."))
33 | 				return
34 | 			}
35 | 
36 | 			ctx := context.WithValue(r.Context(), claimsContextKey, claims)
37 | 			next.ServeHTTP(w, r.WithContext(ctx))
38 | 		})
39 | 	}
40 | }
41 | 
42 | // ClaimsFromContext returns the validated access claims of the current request.
43 | func ClaimsFromContext(ctx context.Context) (*security.AccessClaims, bool) {
44 | 	claims, ok := ctx.Value(claimsContextKey).(*security.AccessClaims)
45 | 	return claims, ok
46 | }
47 | 
48 | // AdminIDFromContext returns the subject (admin_users.id) of the current token.
49 | func AdminIDFromContext(ctx context.Context) (string, bool) {
50 | 	claims, ok := ClaimsFromContext(ctx)
51 | 	if !ok || claims.Subject == "" {
52 | 		return "", false
53 | 	}
54 | 	return claims.Subject, true
55 | }
56 | 
57 | func bearerToken(r *http.Request) string {
58 | 	header := r.Header.Get("Authorization")
59 | 	if header == "" {
60 | 		return ""
61 | 	}
62 | 	parts := strings.SplitN(header, " ", 2)
63 | 	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
64 | 		return ""
65 | 	}
66 | 	return strings.TrimSpace(parts[1])
67 | }
68 | 
69 | // writeAuthError renders the shared JSON error envelope without importing the
70 | // handler package (which would create a cycle).
71 | func writeAuthError(w http.ResponseWriter, err error) {
72 | 	apiErr := apierr.From(err)
73 | 	w.Header().Set("Content-Type", "application/json; charset=utf-8")
74 | 	w.Header().Set("Cache-Control", "no-store")
75 | 	if apiErr.Status == http.StatusUnauthorized {
76 | 		w.Header().Set("WWW-Authenticate", `Bearer realm="portfolio-api"`)
77 | 	}
78 | 	w.WriteHeader(apiErr.Status)
79 | 	_, _ = w.Write([]byte(`{"error":{"code":"` + apiErr.Code + `","message":` + quote(apiErr.Message) + `}}`))
80 | }
81 | 
82 | func quote(v string) string {
83 | 	replacer := strings.NewReplacer(`\`, `\\`, `"`, `\"`)
84 | 	return `"` + replacer.Replace(v) + `"`
85 | }
